#!/usr/bin/env bash
#
# check-goldens-ast.sh - the static golden gate for ct-ast (SH-105, gate 12).
#
# This is the L1/L2-free oracle: it takes one ct-ast binary and compares its
# output for every test/cases/*.ct with the committed static expectation under
# test/goldens/ast/<case>.c.  It builds no L0/L1/L2 chain and does not read
# selfhost/l1 or selfhost/l2, so it keeps working after those layers retire.
#
# The banner names the compiler version ("Generated by ct v0.88.3 ..."), which
# would otherwise turn every version bump into 25 golden diffs.  Both sides are
# normalised with `s/v<digits>.<digits>.<digits>/vX/g` before the byte compare;
# the committed golden keeps the version that generated it.
#
# Coverage is part of the verdict: a case without a golden and a golden without
# a case are both failures, never a silent skip.
#
# Usage: bash selfhost/check-goldens-ast.sh <ct-ast-binary>
#        CHECK_GOLDENS_AST_DIR=<dir>   test-only golden-directory override
#        CHECK_GOLDENS_AST_CASES=<dir> test-only case-directory override
# Exit: 0 all cases match, 1 any mismatch/missing/extra/compile failure.
set -u

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root" || exit 1

CT="${1:?usage: check-goldens-ast.sh <ct-ast-binary>}"
if [ ! -x "$CT" ]; then
    echo "check-goldens-ast: FAIL: not an executable ct-ast binary: $CT" >&2
    exit 1
fi
cases="${CHECK_GOLDENS_AST_CASES:-$root/test/cases}"
goldens="${CHECK_GOLDENS_AST_DIR:-$root/test/goldens/ast}"
if [ ! -d "$cases" ]; then
    echo "check-goldens-ast: FAIL: cases directory missing: $cases" >&2
    exit 1
fi
if [ ! -d "$goldens" ]; then
    echo "check-goldens-ast: FAIL: goldens directory missing: $goldens" >&2
    exit 1
fi

work="$(mktemp -d "${TMPDIR:-/tmp}/ct-ast-goldens.XXXXXX")" || exit 1
trap 'rm -rf "$work"' EXIT HUP INT TERM

normalise() { # file
    sed -E 's/v[0-9]+\.[0-9]+\.[0-9]+/vX/g' "$1"
}

pass=0
fail=0
total=0

set -- "$cases"/*.ct
if [ ! -e "$1" ]; then
    echo "check-goldens-ast: FAIL: no .ct cases under $cases" >&2
    exit 1
fi

for src in "$@"; do
    b="$(basename "$src" .ct)"
    total=$((total + 1))
    golden="$goldens/$b.c"
    if [ ! -f "$golden" ]; then
        echo "FAIL $b (golden missing: test/goldens/ast/$b.c)"
        fail=$((fail + 1))
        continue
    fi
    out="$work/$b.c"
    # The banner records the input path; use the repo-relative spelling the
    # goldens were generated with so an absolute invocation is still canonical.
    src_arg="$src"
    case "$src" in
        "$root"/*) src_arg="${src#"$root"/}" ;;
    esac
    if ! CT_STD_DIR="$root/lib/std" "$CT" "$src_arg" -o "$out" >"$work/$b.log" 2>&1; then
        echo "FAIL $b (ct-ast exit $?): $(head -n 1 "$work/$b.log")"
        fail=$((fail + 1))
        continue
    fi
    if [ ! -f "$out" ]; then
        echo "FAIL $b (ct-ast wrote no .c)"
        fail=$((fail + 1))
        continue
    fi
    normalise "$golden" >"$work/$b.want"
    normalise "$out" >"$work/$b.got"
    if cmp -s "$work/$b.want" "$work/$b.got"; then
        echo "PASS $b"
        pass=$((pass + 1))
    else
        echo "FAIL $b (ct-ast output differs from test/goldens/ast/$b.c)"
        diff -u "$work/$b.want" "$work/$b.got" | head -n 12 | sed 's/^/    /'
        fail=$((fail + 1))
    fi
done

# A golden without a case means the corpus shrank; report it instead of
# leaving an unreachable expectation behind.
for golden in "$goldens"/*.c; do
    [ -e "$golden" ] || continue
    b="$(basename "$golden" .c)"
    if [ ! -f "$cases/$b.ct" ]; then
        echo "FAIL $b (golden has no test/cases/$b.ct)"
        fail=$((fail + 1))
    fi
done

if [ "$fail" -eq 0 ]; then
    echo "check-goldens-ast: $pass/$total"
else
    echo "check-goldens-ast: FAIL ($pass/$total passed, $fail failure(s))"
fi
[ "$fail" -eq 0 ]
